 * not share the usage-rollup batch, so a workspace is removed once its
 * retention window has closed whether or not that batch has reached it.
 */
export async function listDeletedOrgsBefore(
  before: IsoTimestamp,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select()
    .from(organizations)
    .where(
