const RETENTION_MS = DELETED_WORKSPACE_RETENTION_DAYS * 24 * 60 * 60 * 1000;

/**
 * Brings a deleted workspace back. There is no `Actor` to resolve while the
 * workspace is deleted, so the caller is named by user id and checked against
 * the membership row directly.
 *
 * Unknown workspace, a caller who is not a member, and a closed retention
 * window are all `NotFoundError` — the workspace is gone. A member who is not
 * an owner fails the `org:restore` check. A workspace that is not deleted is
 * returned unchanged and publishes nothing.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) throw new NotFoundError("Organization", orgId);

  const member = await memberRepo.findMember(orgId, userId);
  if (!member) throw new NotFoundError("Organization", orgId);

  if (org.archivedAt !== null) {
    const ageMs = Date.now() - new Date(org.archivedAt).getTime();
    if (ageMs >= RETENTION_MS) {
      throw new NotFoundError("Organization", orgId);
    }
  }

  if (org.archivedAt === null) return org;

  assertCan(
    { userId, orgId, role: member.role },
    "org:restore",
    orgResource(orgId),
  );

  const restored = await orgRepo.restoreOrg(orgId);

  await emit("organization.restored", {
    ...envelope(restored.id, userId),
    slug: restored.slug,
  });

  return restored;
}

