import { eq } from "drizzle-orm";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { DELETED_WORKSPACE_RETENTION_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { runOverdueIssueJob, resetOverdueTracking } from "@/server/jobs/overdue-issue-job";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import { runWebhookDeliveryJob } from "@/server/jobs/webhook-delivery-job";
import { getDb, issues, organizations, sessions, subscriptions, users, webhookDeliveries } from "@/server/db";
import { newId } from "@/lib/id";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as invitationService from "@/server/services/invitation-service";
import { notify } from "@/server/services/notification-service";
import * as orgService from "@/server/services/organization-service";
import { NotFoundError } from "@/server/services/_support";
import { listActivity } from "@/server/services/activity-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

const DAY = 24 * 60 * 60 * 1000;

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("retain");
  await usageRepo.recomputeUsage(tenant.org.id);
});

afterAll(() => {
  cleanup();
});

describe("workspace deletion retention", () => {
  it("deletes softly, reserves the slug, hides the workspace, and audits", async () => {
    const seen: string[] = [];
    const off = subscribe("organization.deleted", (payload) => {
      seen.push(payload.slug);
    });
    const detachAudit = registerActivityListeners();

    const deleted = await orgService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    expect(deleted.archivedAt).not.toBeNull();
    expect(seen).toEqual([tenant.org.slug]);
    await expect(
      orgService.deleteOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        confirmSlug: tenant.org.slug,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    expect(await orgRepo.findOrgBySlug(tenant.org.slug)).toBeNull();
    expect(await orgService.listOrganizationsForUser(tenant.userIds.owner)).toEqual([]);

    const again = await orgService.createOrganization(tenant.userIds.owner, {
      name: "Retain again",
      slug: tenant.org.slug,
      plan: "growth",
    });
    expect(again.slug).not.toBe(tenant.org.slug);

    const audit = await listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["organization.deleted"],
      limit: 10,
      cursor: null,
    });
    expect(audit.items[0]).toMatchObject({
      action: "organization.deleted",
      actorId: tenant.userIds.owner,
      subjectKind: "organization",
      subjectId: tenant.org.id,
    });

    off();
    detachAudit();
  });

  it("restores for an owner, refuses other members, and ignores a live workspace", async () => {
    const seen: string[] = [];
    const off = subscribe("organization.restored", (payload) => {
      seen.push(`${payload.actorId}:${payload.slug}`);
    });

    await expect(
      orgService.restoreOrganization(tenant.userIds.admin, tenant.org.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const stranger = await userRepo.insertUser({
      email: "stranger@retain.test",
      name: "Stranger",
      passwordHash: "seed",
    });
    await expect(
      orgService.restoreOrganization(stranger.id, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      orgService.restoreOrganization(tenant.userIds.owner, "01HZZZNOORGNOORGNOORGNOORG" as typeof tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const restored = await orgService.restoreOrganization(
      tenant.userIds.owner,
      tenant.org.id,
    );
    expect(restored.archivedAt).toBeNull();
    expect(seen).toEqual([`${tenant.userIds.owner}:${tenant.org.slug}`]);
    expect((await orgRepo.findOrgBySlug(tenant.org.slug))?.id).toBe(tenant.org.id);
    expect(
      (await orgService.listOrganizationsForUser(tenant.userIds.owner)).map((org) => org.id),
    ).toContain(tenant.org.id);

    seen.length = 0;
    const again = await orgService.restoreOrganization(
      tenant.userIds.owner,
      tenant.org.id,
    );
    expect(again.id).toBe(tenant.org.id);
    expect(again.archivedAt).toBeNull();
    expect(seen).toEqual([]);

    off();
  });

  it("closes the window even before the purge runs", async () => {
    await orgService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });
    const closed = toIsoTimestamp(
      new Date(Date.now() - DELETED_WORKSPACE_RETENTION_DAYS * DAY),
    );
    getDb()
      .update(organizations)
      .set({ archivedAt: closed })
      .where(eq(organizations.id, tenant.org.id))
      .run();

    await expect(
      orgService.restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const still = await orgRepo.findOrgById(tenant.org.id);
    expect(still?.archivedAt).toBe(closed);
  });

  it("does nothing inside a deleted workspace", async () => {
    const fresh = toIsoTimestamp(new Date());
    getDb()
      .update(organizations)
      .set({ archivedAt: fresh })
      .where(eq(organizations.id, tenant.org.id))
      .run();

    const rows = await notify(tenant.org.id, "member_joined", [tenant.userIds.admin], {
      title: "nope",
      body: "nope",
      href: "/settings/members",
      actorId: null,
    });
    expect(rows).toEqual([]);

    const token = "invite-token-retain";
    await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "new@retain.test",
        role: "member",
        expiresInDays: 7,
      },
      tenant.userIds.owner,
      hashToken(token),
    );
    const invitee = await userRepo.insertUser({
      email: "new@retain.test",
      name: "New",
      passwordHash: "seed",
    });
    await expect(
      invitationService.acceptInvitation(invitee.id, { token }),
    ).rejects.toBeInstanceOf(NotFoundError);
    const pending = await invitationRepo.listPendingInvitations(tenant.org.id);
    expect(pending.some((row) => row.email === "new@retain.test")).toBe(true);

    const issue = await issueRepo.insertIssue(
      tenant.org.id,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "still late",
        dueAt: "2020-01-01T00:00:00.000Z",
        assigneeId: tenant.userIds.member,
      }),
      tenant.userIds.owner,
    );
    resetOverdueTracking();
    const overdue: string[] = [];
    const off = subscribe("issue.overdue", (payload) => {
      overdue.push(payload.issueId);
    });
    await runOverdueIssueJob(new Date());
    expect(overdue).not.toContain(issue.id);
    off();

    const before = await usageRepo.getUsage(tenant.org.id);
    await runUsageRollupJob(new Date());
    const after = await usageRepo.getUsage(tenant.org.id);
    expect(after.measuredAt).toBe(before.measuredAt);

    getDb()
      .update(subscriptions)
      .set({
        status: "trialing",
        plan: "growth",
        currentPeriodEnd: "2020-01-01T00:00:00.000Z",
      })
      .where(eq(subscriptions.orgId, tenant.org.id))
      .run();
    await runTrialExpiryJob(new Date());
    const sub = await subscriptionRepo.getSubscription(tenant.org.id);
    expect(sub?.plan).toBe("growth");
    expect(sub?.status).toBe("trialing");

    const endpoint = await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://example.test/hook",
        eventTypes: ["issue.created"],
      },
      "secret",
    );
    await webhookRepo.enqueueDelivery(
      tenant.org.id,
      endpoint.id,
      "issue.created",
      "{}",
    );
    await runWebhookDeliveryJob(new Date());
    const delivery = getDb()
      .select()
      .from(webhookDeliveries)
      .where(eq(webhookDeliveries.orgId, tenant.org.id))
      .all();
    expect(delivery.every((row) => row.status === "failed")).toBe(true);
    expect(delivery.some((row) => row.status === "delivered")).toBe(false);
  });

  it("purges only workspaces whose deletion is at least the window old", async () => {
    const sessionId = newId();
    getDb()
      .insert(sessions)
      .values({
        id: sessionId,
        userId: tenant.userIds.owner,
        activeOrgId: tenant.org.id,
        tokenHash: `hash-${sessionId}`,
        expiresAt: toIsoTimestamp(new Date(Date.now() + DAY)),
        createdAt: toIsoTimestamp(new Date()),
        updatedAt: toIsoTimestamp(new Date()),
      })
      .run();

    const young = toIsoTimestamp(new Date(Date.now() - (DELETED_WORKSPACE_RETENTION_DAYS * DAY - 1000)));
    getDb()
      .update(organizations)
      .set({ archivedAt: young })
      .where(eq(organizations.id, tenant.org.id))
      .run();

    await runCleanupArchivedJob(new Date());
    expect(await orgRepo.findOrgById(tenant.org.id)).not.toBeNull();
    expect(await issueRepo.findIssueById(tenant.org.id, (await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 10,
      cursor: null,
      includeArchived: true,
    })).items[0]!.id)).not.toBeNull();

    const old = toIsoTimestamp(new Date(Date.now() - DELETED_WORKSPACE_RETENTION_DAYS * DAY));
    getDb()
      .update(organizations)
      .set({ archivedAt: old })
      .where(eq(organizations.id, tenant.org.id))
      .run();

